class r{arrayToVector(r){return r}vectorToArray(r){return r instanceof Float32Array?r:new Float32Array(r)}Windowing(r){return{frame:r}}Spectrum(r){const t=r.length||1024,e=new Float32Array(t/2);for(let n=0;n<e.length;n++)e[n]=.1*Math.random()*Math.exp(-n/e.length);return{spectrum:e}}SpectralCentroidTime(r,t){return{spectralCentroid:1e3+500*Math.random()}}ZeroCrossingRate(r){return{zeroCrossingRate:.05+.05*Math.random()}}MFCC(r,t,e){return{mfcc:Array.from({length:t},()=>2*Math.random()-1)}}RhythmExtractor2013(r,t){return{bpm:120+20*Math.random(),confidence:.8+.15*Math.random(),beats:[0,.5,1,1.5],ticks:[0,.25,.5,.75,1]}}KeyExtractor(r,t,e,n,a){const o=["C","C#","D","D#","E","F","F#","G","G#","A","A#","B"],l=["major","minor"];return{key:o[Math.floor(Math.random()*o.length)],scale:l[Math.floor(Math.random()*l.length)],strength:.7+.25*Math.random()}}PitchMelodia(r,t){const e=r.length||1024,n=Math.floor(e/(t.hopSize||512));return{pitch:new Float32Array(n).fill(440),pitchConfidence:new Float32Array(n).fill(.95)}}HPCP(r,t){return{hpcp:new Float32Array(12).fill(.1)}}ChordsDetection(r,t){return{chords:["C","C","G","G"],strength:new Float32Array([.9,.85,.88,.92])}}MelBands(r,t,e){return{melBands:new Float32Array(t).fill(.05)}}delete(r){}}let t=null;async function e(){return t||(t=new r),t}export{r as MockEssentia,e as getMockEssentiaInstance};
